js-contains-duplicate.solution:
function containsDuplicate(nums) {
  const seen = new Set();
  for (const x of nums) {
    if (seen.has(x)) return true;
    seen.add(x);
  }
  return false;
}

js-two-sum.solution:
function twoSum(nums, target) {
  const indexOf = new Map();          // value -> index where we saw it
  for (let i = 0; i < nums.length; i++) {
    const need = target - nums[i];
    if (indexOf.has(need)) return [indexOf.get(need), i];
    indexOf.set(nums[i], i);
  }
  return [];
}

js-group-anagrams.solution:
function groupAnagrams(strs) {
  const groups = new Map();                 // signature -> array of words
  for (const word of strs) {
    const counts = new Array(26).fill(0);
    for (let i = 0; i < word.length; i++) counts[word.charCodeAt(i) - 97]++;
    const key = counts.join(",");          // e.g. "1,0,0,...": unambiguous
    if (!groups.has(key)) groups.set(key, []);
    groups.get(key).push(word);
  }
  return [...groups.values()];
}

js-top-k-frequent-elements.solution:
function topKFrequent(nums, k) {
  const freq = new Map();
  for (const x of nums) freq.set(x, (freq.get(x) || 0) + 1);
  // bucket[c] holds the values that occur exactly c times
  const bucket = Array.from({ length: nums.length + 1 }, () => []);
  for (const [value, c] of freq) bucket[c].push(value);
  const out = [];
  for (let c = nums.length; c >= 1 && out.length < k; c--) {
    for (const v of bucket[c]) {
      out.push(v);
      if (out.length === k) break;
    }
  }
  return out;
}

js-product-of-array-except-self.solution:
function productExceptSelf(nums) {
  const n = nums.length;
  const out = new Array(n).fill(1);
  let prefix = 1;
  for (let i = 0; i < n; i++) {   // out[i] = product of everything to the left
    out[i] = prefix;
    prefix *= nums[i];
  }
  let suffix = 1;
  for (let i = n - 1; i >= 0; i--) { // multiply in everything to the right
    out[i] *= suffix;
    suffix *= nums[i];
  }
  return out;
}

js-longest-consecutive-sequence.solution:
function longestConsecutive(nums) {
  const set = new Set(nums);
  let best = 0;
  for (const x of set) {
    if (set.has(x - 1)) continue;     // x is not the start of a run
    let len = 1;
    while (set.has(x + len)) len++;
    if (len > best) best = len;
  }
  return best;
}

js-valid-palindrome.solution:
function isAlnum(code) {
  return (code >= 48 && code <= 57) || (code >= 65 && code <= 90) || (code >= 97 && code <= 122);
}
function isPalindrome(s) {
  let i = 0, j = s.length - 1;
  while (i < j) {
    while (i < j && !isAlnum(s.charCodeAt(i))) i++;
    while (i < j && !isAlnum(s.charCodeAt(j))) j--;
    if (s[i].toLowerCase() !== s[j].toLowerCase()) return false;
    i++;
    j--;
  }
  return true;
}

