  let i = 0, j = numbers.length - 1;
  while (i < j) {
    const sum = numbers[i] + numbers[j];
    if (sum === target) return [i + 1, j + 1];
    if (sum < target) i++;     // need a bigger sum
    else j--;                  // need a smaller sum
  }
  return [];
}

