js-evaluate-reverse-polish-notation.solution:
function evalRPN(tokens) {
  const st = [];
  for (const tok of tokens) {
    if (tok === "+" || tok === "-" || tok === "*" || tok === "/") {
      const b = st.pop(), a = st.pop();      // b was pushed last: it is the RIGHT operand
      if (tok === "+") st.push(a + b);
      else if (tok === "-") st.push(a - b);
      else if (tok === "*") st.push(a * b);
      else st.push(Math.trunc(a / b));       // toward zero, unlike Math.floor
    } else {
      st.push(Number(tok));
    }
  }
  return st[0];
}

js-daily-temperatures.solution:
function dailyTemperatures(temperatures) {
  const n = temperatures.length;
  const ans = new Array(n).fill(0);
  const stack = [];                  // indices of days still waiting; temps decreasing
  for (let i = 0; i < n; i++) {
    while (stack.length && temperatures[stack[stack.length - 1]] < temperatures[i]) {
      const j = stack.pop();
      ans[j] = i - j;                 // day i is the first warmer day for j
    }
    stack.push(i);
  }
  return ans;
}

js-binary-search.solution:
function search(nums, target) {
  let lo = 0, hi = nums.length - 1;
  while (lo <= hi) {
    const mid = lo + ((hi - lo) >> 1);    // integer midpoint
    if (nums[mid] === target) return mid;
    if (nums[mid] < target) lo = mid + 1;
    else hi = mid - 1;
  }
  return -1;
}

js-koko-eating-bananas.solution:
function minEatingSpeed(piles, h) {
  let lo = 1, hi = Math.max(...piles);      // speed hi always works
  while (lo < hi) {
    const k = Math.floor((lo + hi) / 2);
    let hours = 0;
    for (const p of piles) hours += Math.ceil(p / k);
    if (hours <= h) hi = k;                 // k works: try slower
    else lo = k + 1;                        // too slow
  }
  return lo;
}

js-search-in-rotated-sorted-array.solution:
function search(nums, target) {
  let lo = 0, hi = nums.length - 1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (nums[mid] === target) return mid;
    if (nums[lo] <= nums[mid]) {                       // left half lo..mid is sorted
      if (nums[lo] <= target && target < nums[mid]) hi = mid - 1;
      else lo = mid + 1;
    } else {                                           // right half mid..hi is sorted
      if (nums[mid] < target && target <= nums[hi]) lo = mid + 1;
      else hi = mid - 1;
    }
  }
  return -1;
}

js-find-minimum-in-rotated-sorted-array.solution:
function findMin(nums) {
  let lo = 0, hi = nums.length - 1;
  while (lo < hi) {
    const mid = (lo + hi) >> 1;
    if (nums[mid] > nums[hi]) lo = mid + 1;   // the drop is to the right of mid
    else hi = mid;                            // mid could be the minimum
  }
  return nums[lo];
}

