js-lru-cache-design.solution:
class DNode {
  constructor(key, val) { this.key = key; this.val = val; this.prev = null; this.next = null; }
}
class LRUCache {
  constructor(capacity) {
    this.cap = capacity;
    this.map = new Map();                 // key -> DNode
    this.head = new DNode(0, 0);          // sentinel: most recent side
    this.tail = new DNode(0, 0);          // sentinel: least recent side
    this.head.next = this.tail;
    this.tail.prev = this.head;
  }
  unlink(node) {
    node.prev.next = node.next;
    node.next.prev = node.prev;
  }
  pushFront(node) {
    node.next = this.head.next;
    node.prev = this.head;
    this.head.next.prev = node;
    this.head.next = node;
  }
  get(key) {
    const node = this.map.get(key);
    if (!node) return -1;
    this.unlink(node);
    this.pushFront(node);
    return node.val;
  }
  put(key, value) {
    let node = this.map.get(key);
    if (node) {
      node.val = value;
      this.unlink(node);
    } else {
      node = new DNode(key, value);
      this.map.set(key, node);
      if (this.map.size > this.cap) {
        const lru = this.tail.prev;       // least recently used real node
        this.unlink(lru);
        this.map.delete(lru.key);
      }
    }
    this.pushFront(node);
  }
}

