js-subsets.solution:
function subsets(nums) {
  const result = [], path = [];
  function backtrack(i) {
    if (i === nums.length) {
      result.push([...path]);        // COPY: path keeps changing afterwards
      return;
    }
    path.push(nums[i]);              // choice 1: take nums[i]
    backtrack(i + 1);
    path.pop();                      // undo
    backtrack(i + 1);                // choice 2: skip nums[i]
  }
  backtrack(0);
  return result;
}

