  for (let i = 0; i < 32; i++) {
    res = (res << 1) | (n & 1);   // append n's lowest bit to res
    n >>>= 1;                     // unsigned shift: no sign bit copied in
  }
  return res >>> 0;               // reinterpret the 32 bits as unsigned
}

